import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"Models Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"models-configuration.md","filePath":"models-configuration.md"}'),s={name:"models-configuration.md"};function a(i,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="models-configuration" tabindex="-1">Models Configuration <a class="header-anchor" href="#models-configuration" aria-label="Permalink to &quot;Models Configuration&quot;">​</a></h1><p>This reference lists the fields of <code>models.json</code>. See <a href="./models.html#configure-a-compatible-endpoint">Configure a compatible endpoint</a> for examples and <a href="./configuration.html#agent-directory">Configuration</a> for the file location.</p><p>Add <code>&quot;$schema&quot;: &quot;https://pi.dev/schemas/models.schema.json&quot;</code> to <code>models.json</code> for editor validation and completion.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Each key under <code>providers</code> is a provider ID. A built-in provider ID changes that provider. Any other ID adds a provider, which needs <code>baseUrl</code> and an <code>api</code> at provider or model level.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td></td><td>Display name.</td></tr><tr><td><code>baseUrl</code></td><td>string</td><td></td><td>API base URL. Also applies to the provider&#39;s built-in models.</td></tr><tr><td><code>apiKey</code></td><td>string</td><td></td><td>Literal key, &quot;$NAME&quot; environment interpolation, or &quot;!command&quot; output.</td></tr><tr><td><code>api</code></td><td>string</td><td></td><td>API for the provider&#39;s models, such as &quot;openai-completions&quot;, &quot;openai-responses&quot;, &quot;anthropic-messages&quot;, or &quot;google-generative-ai&quot;.</td></tr><tr><td><code>oauth</code></td><td><code>&quot;radius&quot;</code></td><td></td><td>OAuth login flow. Requires baseUrl.</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>Request headers. Values resolve like apiKey.</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>Provider and model compatibility overrides.</td></tr><tr><td><code>authHeader</code></td><td>boolean</td><td><code>false</code></td><td>Whether to send the resolved API key as Authorization: Bearer.</td></tr><tr><td><code>models</code></td><td><a href="#models"><code>object[]</code></a></td><td></td><td></td></tr><tr><td><code>modelOverrides</code></td><td><a href="#model-overrides">object</a></td><td></td><td></td></tr></tbody></table><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><p>Each <code>models</code> entry adds a model to the provider. An entry whose <code>id</code> matches an existing model replaces it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td></td><td>Required. Model ID sent to the API.</td></tr><tr><td><code>name</code></td><td>string</td><td></td><td>Display name, also matched by --model patterns.</td></tr><tr><td><code>api</code></td><td>string</td><td></td><td>Overrides the provider api.</td></tr><tr><td><code>baseUrl</code></td><td>string</td><td></td><td>Overrides the provider baseUrl.</td></tr><tr><td><code>reasoning</code></td><td>boolean</td><td><code>false</code></td><td>Whether the model supports thinking.</td></tr><tr><td><code>thinkingLevelMap</code></td><td>object</td><td></td><td>Provider value sent for each thinking level. null marks a level unsupported. Levels the model does not map use the provider&#39;s default value through high; xhigh and max are unsupported.</td></tr><tr><td><code>input</code></td><td><code>(&quot;text&quot; | &quot;image&quot;)[]</code></td><td><code>[&quot;text&quot;]</code></td><td></td></tr><tr><td><code>inputLimits</code></td><td><a href="#input-limits">object</a></td><td></td><td></td></tr><tr><td><code>cost</code></td><td>object</td><td></td><td></td></tr><tr><td><code>cost.input</code></td><td>number</td><td></td><td>Required. Input cost in USD per million tokens.</td></tr><tr><td><code>cost.output</code></td><td>number</td><td></td><td>Required. Output cost in USD per million tokens.</td></tr><tr><td><code>cost.cacheRead</code></td><td>number</td><td></td><td>Required. Cache-read cost in USD per million tokens.</td></tr><tr><td><code>cost.cacheWrite</code></td><td>number</td><td></td><td>Required. Cache-write cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers</code></td><td><code>object[]</code></td><td></td><td>Request-wide pricing tiers. The highest matching input threshold applies to the full request.</td></tr><tr><td><code>cost.tiers[].inputTokensAbove</code></td><td>number</td><td></td><td>Required. Use this tier when total request input exceeds this token count.</td></tr><tr><td><code>cost.tiers[].input</code></td><td>number</td><td></td><td>Required. Input cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].output</code></td><td>number</td><td></td><td>Required. Output cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].cacheRead</code></td><td>number</td><td></td><td>Required. Cache-read cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].cacheWrite</code></td><td>number</td><td></td><td>Required. Cache-write cost in USD per million tokens.</td></tr><tr><td><code>promptCache</code></td><td>object</td><td></td><td>Best-effort prompt cache lifetime in seconds for the short and long retention tiers. Pi warms only tiers with a known lifetime.</td></tr><tr><td><code>contextWindow</code></td><td>number</td><td><code>128000</code></td><td>Context window in tokens.</td></tr><tr><td><code>maxTokens</code></td><td>number</td><td><code>16384</code></td><td>Maximum output tokens.</td></tr><tr><td><code>samplingParams</code></td><td>object</td><td></td><td>Fields merged into every request body. Applies only to OpenAI-compatible APIs.</td></tr><tr><td><code>samplingParamsByThinkingLevel</code></td><td>object</td><td></td><td>samplingParams per thinking level, merged over samplingParams.</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>Request headers. Values resolve like apiKey.</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>Provider and model compatibility overrides.</td></tr></tbody></table><h2 id="model-overrides" tabindex="-1">Model overrides <a class="header-anchor" href="#model-overrides" aria-label="Permalink to &quot;Model overrides&quot;">​</a></h2><p>Each <code>modelOverrides</code> key is the ID of a built-in or extension model. Unknown IDs are ignored. Object fields, such as <code>cost</code>, merge with the model&#39;s value field by field; other fields replace it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td></td><td>Display name, also matched by --model patterns.</td></tr><tr><td><code>reasoning</code></td><td>boolean</td><td></td><td>Whether the model supports thinking.</td></tr><tr><td><code>thinkingLevelMap</code></td><td>object</td><td></td><td>Provider value sent for each thinking level. null marks a level unsupported. Levels the model does not map use the provider&#39;s default value through high; xhigh and max are unsupported.</td></tr><tr><td><code>input</code></td><td><code>(&quot;text&quot; | &quot;image&quot;)[]</code></td><td></td><td></td></tr><tr><td><code>inputLimits</code></td><td><a href="#input-limits">object</a></td><td></td><td></td></tr><tr><td><code>cost</code></td><td>object</td><td></td><td></td></tr><tr><td><code>cost.input</code></td><td>number</td><td></td><td>Input cost in USD per million tokens.</td></tr><tr><td><code>cost.output</code></td><td>number</td><td></td><td>Output cost in USD per million tokens.</td></tr><tr><td><code>cost.cacheRead</code></td><td>number</td><td></td><td>Cache-read cost in USD per million tokens.</td></tr><tr><td><code>cost.cacheWrite</code></td><td>number</td><td></td><td>Cache-write cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers</code></td><td><code>object[]</code></td><td></td><td>Request-wide pricing tiers. The highest matching input threshold applies to the full request.</td></tr><tr><td><code>cost.tiers[].inputTokensAbove</code></td><td>number</td><td></td><td>Required. Use this tier when total request input exceeds this token count.</td></tr><tr><td><code>cost.tiers[].input</code></td><td>number</td><td></td><td>Required. Input cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].output</code></td><td>number</td><td></td><td>Required. Output cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].cacheRead</code></td><td>number</td><td></td><td>Required. Cache-read cost in USD per million tokens.</td></tr><tr><td><code>cost.tiers[].cacheWrite</code></td><td>number</td><td></td><td>Required. Cache-write cost in USD per million tokens.</td></tr><tr><td><code>promptCache</code></td><td>object</td><td></td><td>Best-effort prompt cache lifetime in seconds for the short and long retention tiers. Pi warms only tiers with a known lifetime.</td></tr><tr><td><code>contextWindow</code></td><td>number</td><td></td><td>Context window in tokens.</td></tr><tr><td><code>maxTokens</code></td><td>number</td><td></td><td>Maximum output tokens.</td></tr><tr><td><code>samplingParams</code></td><td>object</td><td></td><td>Fields merged into every request body. Applies only to OpenAI-compatible APIs.</td></tr><tr><td><code>samplingParamsByThinkingLevel</code></td><td>object</td><td></td><td>samplingParams per thinking level, merged over samplingParams.</td></tr><tr><td><code>headers</code></td><td>object</td><td></td><td>Request headers. Values resolve like apiKey.</td></tr><tr><td><code>compat</code></td><td><a href="#compatibility">object</a></td><td></td><td>Provider and model compatibility overrides.</td></tr></tbody></table><h2 id="input-limits" tabindex="-1">Input limits <a class="header-anchor" href="#input-limits" aria-label="Permalink to &quot;Input limits&quot;">​</a></h2><p>See <a href="./models.html#describe-model-input-and-caching">Describe model input and caching</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>maxRequestBytes</code></td><td>integer</td><td></td><td>Maximum serialized provider request size in bytes.</td></tr><tr><td><code>images</code></td><td>object</td><td></td><td></td></tr><tr><td><code>images.resize</code></td><td>object</td><td></td><td>Cache-safe resize profile applied before a new image enters conversation history.</td></tr><tr><td><code>images.resize.maxWidth</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.resize.maxHeight</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.resize.maxBytes</code></td><td>integer</td><td></td><td>Maximum base64-encoded payload size in bytes.</td></tr><tr><td><code>images.resize.jpegQuality</code></td><td>integer</td><td></td><td></td></tr><tr><td><code>images.maxPerMessage</code></td><td>integer</td><td></td><td>Maximum images accepted in one provider message.</td></tr><tr><td><code>images.maxPerRequest</code></td><td>integer</td><td></td><td>Maximum images accepted across one provider request.</td></tr></tbody></table><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p><code>compat</code> describes verified differences from an API&#39;s standard request and response behavior. Model values override provider values per field. The fields that apply depend on the model&#39;s <code>api</code>.</p><h3 id="openai-completions" tabindex="-1"><code>openai-completions</code> <a class="header-anchor" href="#openai-completions" aria-label="Permalink to &quot;`openai-completions`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>supportsStore</code></td><td>boolean</td><td></td><td>Whether the provider supports the store field. Default: auto-detected from URL.</td></tr><tr><td><code>supportsDeveloperRole</code></td><td>boolean</td><td></td><td>Whether the provider supports the developer role instead of system. Default: auto-detected from URL.</td></tr><tr><td><code>supportsReasoningEffort</code></td><td>boolean</td><td></td><td>Whether the provider supports reasoning_effort. Default: auto-detected from URL.</td></tr><tr><td><code>supportsUsageInStreaming</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider supports stream_options.include_usage for token usage in streaming responses.</td></tr><tr><td><code>supportsFinishReason</code></td><td>boolean</td><td><code>true</code></td><td>Whether streamed responses include finish_reason. When false, pi infers stop or toolUse when the stream ends.</td></tr><tr><td><code>maxTokensField</code></td><td><code>&quot;max_completion_tokens&quot; | &quot;max_tokens&quot;</code></td><td></td><td>Which field to use for max tokens. Default: auto-detected from URL.</td></tr><tr><td><code>requiresToolResultName</code></td><td>boolean</td><td></td><td>Whether tool results require the name field. Default: auto-detected from URL.</td></tr><tr><td><code>requiresAssistantAfterToolResult</code></td><td>boolean</td><td></td><td>Whether a user message after tool results requires an assistant message in between. Default: auto-detected from URL.</td></tr><tr><td><code>requiresThinkingAsText</code></td><td>boolean</td><td></td><td>Whether thinking blocks must be converted to text blocks with &lt;thinking&gt; delimiters. Default: auto-detected from URL.</td></tr><tr><td><code>requiresReasoningContentOnAssistantMessages</code></td><td>boolean</td><td></td><td>Whether all replayed assistant messages must include an empty reasoning_content field when reasoning is enabled. Default: auto-detected from URL.</td></tr><tr><td><code>thinkingFormat</code></td><td><code>&quot;openai&quot; | &quot;openrouter&quot; | &quot;deepseek&quot; | &quot;together&quot; | &quot;baseten&quot; | &quot;zai&quot; | &quot;qwen&quot; | &quot;chat-template&quot; | &quot;qwen-chat-template&quot; | &quot;string-thinking&quot; | &quot;ant-ling&quot;</code></td><td></td><td>Format for reasoning or thinking parameters. When omitted, Pi auto-detects the format from the provider URL. &quot;openai&quot; uses reasoning_effort, &quot;openrouter&quot; uses reasoning.effort, &quot;deepseek&quot; uses thinking.type plus reasoning_effort when supported, &quot;together&quot; uses reasoning.enabled plus reasoning_effort when supported, &quot;baseten&quot; uses configurable chat_template_args plus reasoning_effort when supported, &quot;zai&quot; uses thinking.type, &quot;qwen&quot; uses top-level enable_thinking, &quot;qwen-chat-template&quot; uses chat_template_kwargs.enable_thinking and preserve_thinking, &quot;chat-template&quot; uses configurable chat_template_kwargs, &quot;string-thinking&quot; uses top-level thinking, and &quot;ant-ling&quot; uses reasoning.effort only when the mapped effort is non-null.</td></tr><tr><td><code>chatTemplateKwargs</code></td><td>object</td><td></td><td>Kwargs sent as chat_template_kwargs when thinkingFormat is &quot;chat-template&quot;. Use $var with &quot;thinking.enabled&quot;, &quot;thinking.effort&quot;, or &quot;thinking.budget&quot; for pi-controlled values.</td></tr><tr><td><code>chatTemplateArgs</code></td><td>object</td><td></td><td>Arguments sent as chat_template_args when thinkingFormat is &quot;baseten&quot;. Use $var with &quot;thinking.enabled&quot;, &quot;thinking.effort&quot;, or &quot;thinking.budget&quot; for pi-controlled values.</td></tr><tr><td><code>openRouterRouting</code></td><td>object</td><td></td><td>OpenRouter provider routing preferences. Controls which upstream providers OpenRouter routes requests to. Sent as the provider field in the OpenRouter API request body. See <a href="https://openrouter.ai/docs/guides/routing/provider-selection" target="_blank" rel="noreferrer">https://openrouter.ai/docs/guides/routing/provider-selection</a>.</td></tr><tr><td><code>vercelGatewayRouting</code></td><td>object</td><td></td><td>Vercel AI Gateway routing preferences. Controls which upstream providers the gateway routes requests to. See <a href="https://vercel.com/docs/ai-gateway/models-and-providers/provider-options" target="_blank" rel="noreferrer">https://vercel.com/docs/ai-gateway/models-and-providers/provider-options</a>.</td></tr><tr><td><code>zaiToolStream</code></td><td>boolean</td><td><code>false</code></td><td>Whether z.ai supports top-level tool_stream for streaming tool call deltas.</td></tr><tr><td><code>thinkingTokenBudgetField</code></td><td><code>&quot;thinking_token_budget&quot; | &quot;thinking_budget&quot; | &quot;thinking_budget_tokens&quot;</code></td><td></td><td>Top-level request field used to cap reasoning tokens from thinkingBudgets. Reasoning and the answer share max_tokens on these endpoints. &quot;thinking_token_budget&quot; is vLLM, &quot;thinking_budget&quot; is Qwen, DashScope, or SGLang, and &quot;thinking_budget_tokens&quot; is llama.cpp. Off by default and not set on the generated catalog.</td></tr><tr><td><code>supportsThinkingTokenBudget</code></td><td>boolean</td><td><code>false</code></td><td>Alias for thinkingTokenBudgetField: &quot;thinking_token_budget&quot; (vLLM). Prefer thinkingTokenBudgetField.</td></tr><tr><td><code>supportsOpenAIGrammarTools</code></td><td>boolean</td><td><code>false</code></td><td>Whether the provider supports OpenAI custom tools with Lark or regex grammar formats. When false, grammar-constrained tools fall back to normal function tools. The generated catalog enables this for capable models.</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model accepts system or developer messages after the conversation has started. When false, later system messages are folded into the leading system message. The generated catalog enables this for verified models.</td></tr><tr><td><code>supportsMidConvoToolAdditions</code></td><td>boolean</td><td><code>false</code></td><td>Whether system messages can introduce additional tools mid-conversation. Requires supportsMidConvoSystemMessages. The generated catalog enables this for capable models.</td></tr><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td><code>false</code></td><td>Whether the provider supports the strict field in tool definitions. Generated capable models enable it explicitly.</td></tr><tr><td><code>cacheControlFormat</code></td><td><code>&quot;anthropic&quot;</code></td><td></td><td>Cache control convention for prompt caching. Anthropic applies cache_control markers to the system prompt, last tool definition, and last user, assistant, or tool-result text content.</td></tr><tr><td><code>sendSessionAffinityHeaders</code></td><td>boolean</td><td></td><td>Whether to send session-affinity data from options.sessionId. Default: true for OpenRouter endpoints, false otherwise.</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openai&quot; | &quot;openai-nosession&quot; | &quot;openrouter&quot;</code></td><td></td><td>Session-affinity header format. openai sends session_id, x-client-request-id, and x-session-affinity; openai-nosession sends x-client-request-id and x-session-affinity; openrouter sends x-session-id. Does not affect prompt_cache_key. Default: auto-detected.</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td></td><td>Whether the provider supports long prompt cache retention (prompt_cache_retention: &quot;24h&quot; or Anthropic-style cache_control.ttl: &quot;1h&quot;, depending on format). Default: auto-detected from provider and URL.</td></tr><tr><td><code>vllmPriority</code></td><td>number</td><td></td><td>vLLM scheduler priority sent as the top-level priority request field. Lower values are handled earlier and the server default is 0. Only meaningful with --scheduling-policy priority. Off by default and not set on the generated catalog.</td></tr></tbody></table><h3 id="openai-responses" tabindex="-1"><code>openai-responses</code> <a class="header-anchor" href="#openai-responses" aria-label="Permalink to &quot;`openai-responses`&quot;">​</a></h3><p>Also applies to <code>azure-openai-responses</code> and <code>openai-codex-responses</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>supportsDeveloperRole</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider supports the developer role instead of system.</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model accepts developer or system messages after the conversation has started. When false, later system messages are folded into the leading system message. The generated catalog enables this for verified models.</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openai&quot; | &quot;openai-nosession&quot; | &quot;openrouter&quot;</code></td><td></td><td>Session-affinity header format. openai sends session_id and x-client-request-id; openai-nosession sends x-client-request-id; openrouter sends x-session-id. Does not affect prompt_cache_key. Default: auto-detected.</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider supports long prompt cache retention. This uses prompt_cache_options.ttl: &quot;30m&quot; on GPT-5.6+ and prompt_cache_retention: &quot;24h&quot; on earlier models.</td></tr><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td></td><td>Whether the provider supports strict JSON-schema function tools. Defaults are API-specific; generated OpenAI models enable it explicitly.</td></tr><tr><td><code>supportsOpenAIGrammarTools</code></td><td>boolean</td><td><code>false</code></td><td>Whether to emit OpenAI custom tools with Lark or regex grammar formats. When false, grammar-constrained tools fall back to normal function tools. The generated catalog enables this for capable models.</td></tr><tr><td><code>supportsAdditionalTools</code></td><td>boolean</td><td><code>false</code></td><td>Whether the model supports message-anchored additional_tools input items.</td></tr><tr><td><code>supportsToolSearch</code></td><td>boolean</td><td><code>false</code></td><td>Whether the model supports client-executed tool search for transcript-anchored additions.</td></tr><tr><td><code>supportsExplicitPromptCacheMode</code></td><td>boolean</td><td><code>false</code></td><td>Whether the model accepts prompt_cache_options. Older OpenAI models reject the parameter.</td></tr><tr><td><code>supportsMidConvoEffort</code></td><td>boolean</td><td><code>false</code></td><td>Whether thinking level changes are sent as configuration_update input items instead of changing reasoning.effort, so a change keeps the prompt cache. Only used by the openai-responses API, and ignored with Sign in with ChatGPT on the openai provider.</td></tr><tr><td><code>supportsMaxOutputTokens</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider accepts max_output_tokens. Some Codex-protocol gateways reject it.</td></tr></tbody></table><h3 id="anthropic-messages" tabindex="-1"><code>anthropic-messages</code> <a class="header-anchor" href="#anthropic-messages" aria-label="Permalink to &quot;`anthropic-messages`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>supportsEagerToolInputStreaming</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider accepts per-tool eager_input_streaming. When false, the Anthropic provider omits tools[].eager_input_streaming and sends the legacy fine-grained-tool-streaming-2025-05-14 beta header for tool-enabled requests.</td></tr><tr><td><code>supportsLongCacheRetention</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider supports Anthropic long cache retention through cache_control.ttl.</td></tr><tr><td><code>sendSessionAffinityHeaders</code></td><td>boolean</td><td></td><td>Whether to send x-session-affinity from options.sessionId when caching is enabled. Required for providers like Fireworks that use session affinity for prompt cache routing; requests to the same replica maximize cache hits. Default: true for OpenRouter endpoints, false otherwise.</td></tr><tr><td><code>sessionAffinityFormat</code></td><td><code>&quot;openrouter&quot;</code></td><td></td><td>Session-affinity format. openrouter sends x-session-id; when unset, sends x-session-affinity.</td></tr><tr><td><code>supportsCacheControlOnTools</code></td><td>boolean</td><td><code>true</code></td><td>Whether the provider supports Anthropic-style cache_control markers on tool definitions. When false, cache_control is omitted from tool parameters. Some Anthropic-compatible providers, such as Fireworks, do not support this field on tools and may reject or ignore it.</td></tr><tr><td><code>supportsTemperature</code></td><td>boolean</td><td><code>true</code></td><td>Whether the model accepts the Anthropic temperature request field. Claude Opus 4.7+ rejects non-default values.</td></tr><tr><td><code>forceAdaptiveThinking</code></td><td>boolean</td><td><code>false</code></td><td>Whether to force adaptive thinking (thinking.type: adaptive plus output_config.effort) regardless of model ID. Built-in models that require adaptive thinking set this in generated metadata. Custom Anthropic-compatible providers can set this to true for any model whose upstream requires the adaptive format. Set false to opt out on overridden built-in models.</td></tr><tr><td><code>allowEmptySignature</code></td><td>boolean</td><td><code>false</code></td><td>Whether to replay empty thinking signatures instead of converting thinking to text.</td></tr><tr><td><code>supportsStrictTools</code></td><td>boolean</td><td><code>false</code></td><td>Whether the provider supports Anthropic strict tool schemas. Generated Anthropic models enable it explicitly.</td></tr><tr><td><code>supportsMidConvoEffort</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model transport supports effort-only system messages and thinking binding controls.</td></tr><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model accepts system-role messages inside the conversation. When false, later system messages are folded into the top-level system prompt.</td></tr><tr><td><code>supportsMidConvoToolChanges</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model accepts mid-conversation tool_addition and tool_removal blocks. Requires supportsMidConvoSystemMessages.</td></tr><tr><td><code>allowedFallbackModels</code></td><td><code>object[]</code></td><td></td><td>Models Anthropic accepts for server-side refusal fallback, with local pricing metadata for returned fallback responses. When absent or empty, callers must omit fallbacks; Anthropic rejects the field for models with no permitted fallback targets.</td></tr></tbody></table><h3 id="bedrock-converse-stream" tabindex="-1"><code>bedrock-converse-stream</code> <a class="header-anchor" href="#bedrock-converse-stream" aria-label="Permalink to &quot;`bedrock-converse-stream`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>supportsStrictMode</code></td><td>boolean</td><td><code>false</code></td><td>Whether the model supports Bedrock strict tool schemas.</td></tr></tbody></table><h3 id="mistral-conversations" tabindex="-1"><code>mistral-conversations</code> <a class="header-anchor" href="#mistral-conversations" aria-label="Permalink to &quot;`mistral-conversations`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>supportsMidConvoSystemMessages</code></td><td>boolean</td><td><code>false</code></td><td>Whether the exact model accepts system messages after the conversation has started. When false, later system messages are folded into the leading system message.</td></tr></tbody></table><h3 id="typesafe-system-one" tabindex="-1"><code>typesafe-system-one</code> <a class="header-anchor" href="#typesafe-system-one" aria-label="Permalink to &quot;`typesafe-system-one`&quot;">​</a></h3><p>Also applies to <code>cloudflare-workers-ai-system-one</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>imageInput</code></td><td><code>&quot;assets&quot; | &quot;images&quot; | &quot;state-image-urls&quot;</code></td><td></td><td>How the service takes classifier images. &quot;assets&quot; sends TypeSafe&#39;s assets map (PNG and JPEG) and references the images from the state, as TypeSafe and Jev on Workers AI expect. &quot;images&quot; sends Clef&#39;s images list of data URLs (PNG, JPEG, and WebP, at most four), as Clef on Workers AI expects. &quot;state-image-urls&quot; places image_url parts before the state, as OpenRouter expects; OpenRouter drops assets without an error. Auto-detected from the provider, baseUrl, and model ID. Classifier models read it from the provider-level compat; models and modelOverrides entries apply to chat models only.</td></tr><tr><td><code>sendImageOptInHeader</code></td><td>boolean</td><td></td><td>Whether requests with images send the TypeSafe-Danger-Zone-Images: true header, which TypeSafe&#39;s own API requires for its experimental image input. Defaults to true for the typesafe-system-one API unless the model is detected as OpenRouter.</td></tr></tbody></table>',31)])])}const m=e(s,[["render",a]]);export{u as __pageData,m as default};
